import { Task } from "../task/Task"
import type { ToolUse } from "../../shared/tools"
import { BaseTool, ToolCallbacks } from "./BaseTool"

interface GetWorkspaceFileCountParams {
	extensions?: string[]
}

export class GetWorkspaceFileCountTool extends BaseTool<"get_workspace_file_count"> {
	readonly name = "get_workspace_file_count" as const

	async execute(params: GetWorkspaceFileCountParams, task: Task, callbacks: ToolCallbacks): Promise<void> {
		const { pushToolResult } = callbacks
		try {
			// eslint-disable-next-line @typescript-eslint/no-var-requires
			const fs = require("fs")
			// eslint-disable-next-line @typescript-eslint/no-var-requires
			const path = require("path")
			const extensions = params.extensions?.filter((ext) => typeof ext === "string" && ext.length > 0)
			const hasFilter = !!extensions && extensions.length > 0
			const count = this.countFiles(task.cwd, hasFilter ? extensions : undefined, fs, path)
			const suffix = hasFilter ? `filtered by: ${extensions!.join(", ")}` : "all files"
			pushToolResult(`File count: ${count} (${suffix})`)
		} catch (e) {
			const message = e instanceof Error ? e.message : String(e)
			pushToolResult(`Failed to count workspace files: ${message}`)
		}
	}

	private countFiles(dir: string, extensions: string[] | undefined, fs: any, path: any): number {
		let count = 0
		let entries: any[]
		try {
			entries = fs.readdirSync(dir, { withFileTypes: true })
		} catch {
			// Unreadable directory: skip it rather than failing the whole count
			return 0
		}
		for (const entry of entries) {
			if (entry.name === "node_modules" || entry.name === ".git") continue
			const fullPath = path.join(dir, entry.name)
			if (entry.isDirectory()) {
				count += this.countFiles(fullPath, extensions, fs, path)
			} else if (entry.isFile()) {
				if (!extensions || extensions.includes(path.extname(entry.name))) {
					count++
				}
			}
		}
		return count
	}

	override async handlePartial(task: Task, block: ToolUse<"get_workspace_file_count">): Promise<void> {}
}

export const getWorkspaceFileCountTool = new GetWorkspaceFileCountTool()
